VALUES (38787, 'tt0013055', NULL, 'Day Dreams', 'Day Dreams', 'movie', 1922, 'https://image.tmdb.org/t/p/w500/55Sjvx1iZ4Ue7Q3fBMoa8Tnn6JF.jpg', 'https://image.tmdb.org/t/p/original/awR0VKzQsP9cpJPEvs0Y7e0j3WU.jpg', 'In order to impress the father of a girl he is keen on, a young man goes to the city in search of work. In his letters home he writes of his various jobs which her imagination expands into much nobler ones than those that he is actually attempting.', NULL, NULL, 0.6627, 6.551, 0, 1.02, '2026-11-22 02:35:52', '2026-11-22 02:35:52')
