VALUES (10401, 'tt0144201', NULL, 'The Girl on the Bridge', 'La Fille sur le pont', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/ktNosaDWH4PNcdRaMMwPmc0vuCM.jpg', 'https://image.tmdb.org/t/p/original/jlxwZ7XHK17U4sZUxmDP8iHThC8.jpg', 'It''s night on a Paris bridge. A girl leans over Seine River with tears in her eyes and a violent yearning to drown her sorrows. Out of nowhere someone takes an interest in her. He is Gabor, a knife thrower who needs a human target for his show. The girl, Adele, has never been lucky and nowhere else to go. So she follows him. They travel along the northern bank of the Mediterranean to perform.', NULL, NULL, 1.6295, 7.0, 0, 1.01, '2026-11-22 02:35:52', '2026-11-22 02:35:52')
