VALUES (541560, 'tt8426594', NULL, 'The Wind', 'The Wind', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/kcfPHZHSQODLCWdkUVLYATNyEVo.jpg', 'https://image.tmdb.org/t/p/original/cy70DnmcGf1Vo9XKYrz2t8NUzMS.jpg', 'Lizzy is a tough, resourceful frontierswoman settling a remote stretch of land on the 19th-century American frontier. Isolated from civilization in a desolate wilderness where the wind never stops howling, she begins to sense a sinister presence that seems to be borne of the land itself, and when a newlywed couple arrive at a nearby homestead, their presence amplifies Lizzy''s fears, setting into motion a shocking chain of events.', NULL, NULL, 1.4185, 5.684, 0, 10.01, '2026-11-22 02:35:52', '2026-11-22 02:35:52')
