VALUES (4688, 'tt0445922', NULL, 'Across the Universe', 'Across the Universe', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/447c8Te3DXC46rQvDEixKGO4dS6.jpg', 'https://image.tmdb.org/t/p/original/s2mJnlqvRwVo1XpnmuPGvWso7pJ.jpg', 'When young dockworker Jude leaves Liverpool to find his estranged father in the United States, he is swept up by the waves of change that are re-shaping the nation. Jude falls in love with Lucy, who joins the growing anti-war movement. As the body count in Vietnam rises, political tensions at home spiral out of control and the star-crossed lovers find themselves in a psychedelic world gone mad.', NULL, NULL, 3.2299, 7.113, 0, 2.82208333333333349e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
