VALUES (10150, 'tt0084237', NULL, 'The Last Unicorn', 'The Last Unicorn', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/MRHFtXTjxC74MGCzHACcuqvHiw.jpg', 'https://image.tmdb.org/t/p/original/fwxOQkzYtRVKs3kzcyukdbsyIuh.jpg', 'A unicorn learns from a riddle-speaking butterfly that she is supposedly the last of her kind, all the others having been herded away by the monstrous Red Bull. The unicorn sets out to discover the truth behind the butterfly''s words. She is eventually joined on her quest by Schmendrick, a second-rate magician, and Molly Grue, a middle-aged woman who dreamed all her life of seeing a unicorn. Their journey leads them far from home, all the way to the castle of King Haggard.', NULL, NULL, 3.4202, 7.3, 0, 7.26247761194029806e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
