VALUES (9023, 'tt0166813', NULL, 'Spirit: Stallion of the Cimarron', 'Spirit: Stallion of the Cimarron', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/bBEkKDQFianNYwGWR7gJfPVakmG.jpg', 'https://image.tmdb.org/t/p/original/b8hPBW0NJmiIVzvQjT3CwIpAdzl.jpg', 'Against impossible odds, Spirit, a young mustang, sets out across the majestic wilderness to regain his freedom and save his homeland. Along the way, he forms a friendship with a young Lakota brave, outwits a squadron of soldiers, and ultimately, finds love.', NULL, NULL, 11.957, 7.712, 0, 2.015, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
