VALUES (8835, 'tt0250494', NULL, 'Legally Blonde', 'Legally Blonde', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/9ohlMrJHQqKhfUKh7Zr3JQqHNLZ.jpg', 'https://image.tmdb.org/t/p/original/viU23X3BIycUFf6TOlm9c7TxLgM.jpg', 'Fashionable sorority queen Elle Woods has it all, but, she wants nothing more than to be Mrs. Warner Huntington III. But he dumps her before heading to Harvard Law School. Elle rallies all of her resources and gets into Harvard, determined to win him back. While there, she figures out that there is more to herself than just good looks.', NULL, NULL, 9.3503, 6.8, 0, 3.85405714285714324e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
