VALUES (11309, 'tt0099740', NULL, 'Hardware', 'Hardware', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/ybauOsdo6ColZ1WsALqIYjpUg4X.jpg', 'https://image.tmdb.org/t/p/original/nC1qaINaRBY1crPCQoFVPhSrq16.jpg', 'Mark 13 is a government-built killing machine programmed with artificial intelligence, able to repair and recharge itself from any energy source. Through a series of coincidences, the cyborg''s head ends up in the home of a sculptress as a bizarre Christmas present from her boyfriend. Once inside its new home, the cyborg promptly reconstructs the rest of its body using a variety of household utensils and proceeds to go on a murderous rampage.', NULL, NULL, 1.9977, 6.0, 0, 30.4384, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
