VALUES (49010, 'tt1640459', NULL, 'Hobo with a Shotgun', 'Hobo with a Shotgun', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/xxMaO7VoN2BnZit79PedVHnTjcO.jpg', 'https://image.tmdb.org/t/p/original/7ugJdVksDA4oYCxZY6tHhsG2NyV.jpg', 'A vigilante homeless man pulls into a new city and finds himself trapped in urban chaos, a city where crime rules and where the city''s crime boss reigns. Seeing an urban landscape filled with armed robbers, corrupt cops, abused prostitutes and even a pedophile Santa, the Hobo goes about bringing justice to the city the best way he knows how - with a 20-gauge shotgun. Mayhem ensues when he tries to make things better for the future generation. Street justice will indeed prevail.', NULL, NULL, 2.5094, 5.897, 0, 1.82508333333333325e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
