VALUES (502033, 'tt5363618', NULL, 'Sound of Metal', 'Sound of Metal', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/3178oOJKKPDeQ2legWQvMPpllv.jpg', 'https://image.tmdb.org/t/p/original/7b5R8FfGUzlxfhOkPpL3xyIeuyF.jpg', 'Metal drummer Ruben begins to lose his hearing. When a doctor tells him his condition will worsen, he thinks his career and life is over. His girlfriend Lou checks the former addict into a rehab for the deaf hoping it will prevent a relapse and help him adapt to his new life. After being welcomed and accepted just as he is, Ruben must choose between his new normal and the life he once knew.', NULL, NULL, 4.5845, 7.708, 0, 1.41790909090909096e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
