VALUES (4977, 'tt0851578', NULL, 'Paprika', 'パプリカ', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/nHJljo2Pi7XimYEgV9hvRchQWmg.jpg', 'https://image.tmdb.org/t/p/original/3fgcEjBNrhstYgPlG1c8WT7UpIN.jpg', 'Dr. Atsuko Chiba is a research psychologist who uses a device called the DC Mini to enter her patients'' dreams, wherein she adopts the alter-ego "Paprika". When the device is stolen, she must stop rogue elements from merging the dream and waking worlds.', NULL, NULL, 8.467, 7.812, 0, 7.86662162162162132e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
