VALUES (916224, 'tt16428256', NULL, 'Suzume', 'すずめの戸締まり', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/yStW1TXF5s7Tbtu9KjIZEaWl6HL.jpg', 'https://image.tmdb.org/t/p/original/4tdV5AeojEdbvn6VpeQrbuDlmzs.jpg', 'Suzume, 17, lost her mother as a little girl. On her way to school, she meets a mysterious young man. But her curiosity unleashes a calamity that endangers the entire population of Japan, and so Suzume embarks on a journey to set things right.', NULL, NULL, 12.6411, 7.891, 0, 23.899, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
