VALUES (284, 'tt0053604', NULL, 'The Apartment', 'The Apartment', 'movie', 1960, 'https://image.tmdb.org/t/p/w500/hhSRt1KKfRT0yEhEtRW3qp31JFU.jpg', 'https://image.tmdb.org/t/p/original/vRTKNKNWLZ22fAgPa5kY8wT2b1F.jpg', 'Bud Baxter is a minor clerk in a huge New York insurance company, until he discovers a quick way to climb the corporate ladder. He lends out his apartment to the executives as a place to take their mistresses. Although he often has to deal with the aftermath of their visits, one night he''s left with a major problem to solve.', NULL, NULL, 6.5994, 8.184, 0, 2.09078571428571429e+01, '2026-07-15 12:01:52', '2026-11-22 02:35:52')
