VALUES (419635, 'tt1880399', NULL, 'Kodachrome', 'Kodachrome', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/mseyc8v3UD1DhaZ3kSdXs4Dj9Xf.jpg', 'https://image.tmdb.org/t/p/original/mRnceZhq19AoJf97ueVX7lhAUl5.jpg', 'Matt Ryder is convinced to drive his estranged and dying father Benjamin Ryder cross country to deliver four old rolls of Kodachrome film to the last lab in the world that can develop them before it shuts down for good. Along with Ben''s nurse Zooey, the three navigate a world changing from analogue to digital while trying to put the past behind them.', NULL, NULL, 1.5059, 6.8, 0, 9.68, '2026-07-20 01:02:04', '2026-11-22 02:35:52')
