VALUES (372058, 'tt5311514', NULL, 'Your Name.', '君の名は。', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/vfJFJPepRKapMd5G2ro7klIRysq.jpg', 'https://image.tmdb.org/t/p/original/mMtUybQ6hL24FXo0F3Z4j2KG7kZ.jpg', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.', NULL, NULL, 31.453, 8.492, 0, 36.395, '2026-07-20 04:02:06', '2026-11-22 02:35:52')
