VALUES (566038, 'tt8015444', NULL, 'Last and First Men', 'Last and First Men', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/7B9t8lTFCJQ6GVvSbhrbrA7nsVu.jpg', 'https://image.tmdb.org/t/p/original/m76YNtzkO7G7NzQAosmu6pN1AWf.jpg', 'As the end approaches inexorably, the last humans, living millions of years into the future, send a message to the humanity of the present that is both a plea for help and a warning, but also an epic tale of evolution, decline and hope.', NULL, NULL, 1.5348, 6.22, 0, 1.60985714285714287e+01, '2026-07-20 04:02:06', '2026-11-22 02:35:52')
