VALUES (15856, 'tt0051744', NULL, 'House on Haunted Hill', 'House on Haunted Hill', 'movie', 1959, 'https://image.tmdb.org/t/p/w500/g5kdFt3piV3w1pG65W9sSToJ7HB.jpg', 'https://image.tmdb.org/t/p/original/nxE4O2EFIOfanWkdaCWiBRfwjrn.jpg', 'Frederick Loren invites five strangers to the party of a lifetime and offers each of them $10,000 if they can stay the night in the reportedly haunted house. Armed with a gun for protection, each guest arrives in a hearse and will either leave in it much richer…Or dead.', NULL, NULL, 3.1706, 6.73, 0, 20.951875, '2026-07-20 04:02:06', '2026-11-22 02:35:52')
