VALUES (5123, 'tt0426931', NULL, 'August Rush', 'August Rush', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/oA6ZeICPINiS6YtD5WZeBaGVmuT.jpg', 'https://image.tmdb.org/t/p/original/i3pONuqGZSR3UYOOdBeU2CiQnxj.jpg', 'Evan, a musically gifted orphan, runs away from his orphanage and searches New York City for his birth parents. On his journey, he''s taken under the wing of the Wizard, a homeless man who lives in an abandoned theater. After discovering his talent, the Wizard gives Evan the name "August Rush" and devises a plan to profit from his talent. Little does Evan know that his parents, Lyla and Louis, are searching for him too.', NULL, NULL, 4.031, 7.436, 0, 3.02, '2026-08-03 14:31:56', '2026-11-22 02:35:52')
