VALUES (12233, 'tt0095776', NULL, 'Oliver & Company', 'Oliver & Company', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/dgaSqUHjm4CLOdiiJJJstVdreEe.jpg', 'https://image.tmdb.org/t/p/original/k18aKqDPrbTsijtN9jRpnTHxQks.jpg', 'Putting its own ''twist'' on the story of Oliver Twist, the orange runt of a litter of kittens must fight for survival on the rough streets on New York City, finding unlikely friends in the dogs owned by a down-on-his luck man named Fagin. Soon, Oliver and his new band of comrades must fight for survival when Fagin is unable to pay his debts.', NULL, NULL, 5.2465, 6.731, 0, 9.76, '2026-08-06 03:21:20', '2026-11-22 02:35:52')
