VALUES (12568, 'tt0412536', NULL, 'Brideshead Revisited', 'Brideshead Revisited', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/yCkPDr0Yv8HdrHzKxqToUsZqFLt.jpg', 'https://image.tmdb.org/t/p/original/yXF89vOhQeGl4ayy1jez67zTPHd.jpg', 'Befriended by aristocrat Sebastian Flyte, Oxford student Charles Ryder finds that the power and privilege experienced by the family is seductive. On a visit to the ancestral home, Brideshead, he falls in love with his friend''s sister, Julia.  However, as his ties to the Flytes deepen, Ryder finds himself at odds with their strong Roman Catholicism.', NULL, NULL, 4.8712, 6.3, 0, 9.043333333333333e+00, '2026-08-10 02:34:01', '2026-11-22 02:35:52')
