VALUES (396806, 'tt5397194', NULL, 'Anon', 'Anon', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/xhBTO9n3fxy3HJt7WlR9h9vvVmk.jpg', 'https://image.tmdb.org/t/p/original/uugcOIfnh8Gz0nxUbduWCoxjWct.jpg', 'Set in a near-future world where there is no privacy, ignorance or anonymity, our private memories are recorded and crime almost ceases to exist. In trying to solve a series of unsolved murders, Sal Frieland stumbles onto a young woman who appears to have subverted the system and disappeared. She has no identity, no history and no record. Sal realizes it may not be the end of crime but the beginning. Known only as ''The Girl'', Sal must find her before he becomes the next victim.', NULL, NULL, 3.4939, 6.0, 0, 6.51500000000000056e+00, '2026-08-10 02:34:01', '2026-11-22 02:35:52')
